import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';
const root=path.resolve('runtime'),{RemoteD1Database}=await import(pathToFileURL(path.join(root,'report2-d1-adapter.mjs')));
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN);const original=db._request.bind(db);
db._request=async p=>{assert.ok(['all','first'].includes(p.op)&&/^\s*(SELECT|EXPLAIN QUERY PLAN)\b/.test(p.sql)&&!/\b(INSERT|DELETE|UPDATE|CREATE|DROP|ALTER)\b/i.test(p.sql));const u=db.usageSnapshot();assert.ok(u.rows_read<250&&u.rows_written===0&&u.unknown_ops===0&&u.requests<8);return original(p);};
const T=1791225050790,records={},checks=[
['shadow_decision_log','SELECT * FROM shadow_decision_log WHERE shadow_id=?1','1791225015208:ZEC-USDT'],
['v3_early_candidate_wave','SELECT * FROM v3_early_candidate_wave WHERE wave_id=?1','EDW:ZEC-USDT:1791187242450:G3'],
['v3_user_lifecycle_shadow','SELECT * FROM v3_user_lifecycle_shadow WHERE contract=?1 AND wave_id=?2 AND updated_ts<=?3 LIMIT 2','ZEC-USDT','EDW:ZEC-USDT:1791187242450:G3',T]];
for(const [table,sql,...args] of checks){const plan=(await db.prepare('EXPLAIN QUERY PLAN '+sql).bind(...args).all()).results;if(plan.some(p=>/^SCAN /i.test(p.detail)&&!p.detail.includes('USING INDEX'))){records[table]={status:'UNBOUNDED_PLAN_REJECTED',plan};continue;}try{records[table]={rows:(await db.prepare(sql).bind(...args).all()).results};}catch(e){records[table]={error:String(e.message).slice(0,160)};}}
const source=fs.readFileSync(path.join(root,'src/v3-telegram-lifecycle-sidecar.mjs'),'utf8').split('\n');const lineage=source.map((line,index)=>({line:index+1,code:line})).filter(r=>/direction|interest|final_decision|shadow_decision|direction_state|DIRECTION_NOT_CLOSED|ORDER BY|WHERE|snapshot_id/.test(r.code)).slice(0,130);
fs.writeFileSync('audit-output/exact-direction-input-lineage.json',JSON.stringify({schema:'report2-exact-original-direction-lineage-readonly-v1',source_run_id:'1791224954306-1791224965631',original_cutoff:T,read_at:Date.now(),records,lifecycle_lineage:lineage,current_wave_rows_are_not_historical_if_last_seen_after_cutoff:true,sourceHTTP:0,MAIN:0,Telegram:0,usage:db.usageSnapshot(),secrets_included:false},null,2));console.log(JSON.stringify({status:'READ_ONLY_COMPLETE',sourceHTTP:0,MAIN:0,Telegram:0,usage:db.usageSnapshot()}));
